/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
frames = np.load('source_pixels.npz')['rgb']
def detect(img):
    r,g,b = img[...,0].astype(int), img[...,1].astype(int), img[...,2].astype(int)
    mask = (g>140)&(r>120)&(b<120)&(g-b>60)&(r-b>40)
    ys,xs = np.nonzero(mask)
    if len(xs)==0: return (np.nan,np.nan)
    return (xs.mean(), ys.mean())
tr = np.array([detect(f) for f in frames])
for i,(x,y) in enumerate(tr):
    print(i, round(x,2), round(y,2))
\""
